#!/usr/bin/env python3
import json, sys
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
N = 15

# Precompute all possible triples where a+b=c and all three are distinct members of L
triples = []
Lset = set(L)
for i in range(len(L)):
    for j in range(i+1, len(L)):
        a, b = L[i], L[j]
        c = a + b
        if c in Lset and c != a and c != b:
            triples.append((a, b, c))

# Backtracking search for exact cover of 45 numbers using 15 triples
used = set()
solution = []

def backtrack(start):
    if len(solution) == N:
        return True
    # select next unused number to branch on for pruning
    for idx in range(start, len(triples)):
        a, b, c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(idx + 1):
            return True
        # undo
        used.difference_update([a, b, c])
        solution.pop()
    return False

found = backtrack(0)
if not found:
    print("No valid partition exists.")
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "Exhaustive search found no covering set of triples."}
else:
    print("Valid partition found:")
    for t in solution:
        print(t)
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
# Emit witness line for host verification
print("WITNESS: " + json.dumps(witness))
